#!/usr/bin/env bash
# Question 1: Frontend cannot reach api. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "secure" >/dev/null 2>&1 || kubectl get namespace "secure" >/dev/null
timeout 60 bash -c "until kubectl -n 'secure' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: api
  namespace: secure
spec:
  replicas: 2
  selector:
    matchLabels: { app: api }
  template:
    metadata:
      labels: { app: api }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: api
  namespace: secure
spec:
  selector: { app: api }
  ports: [{ port: 80, targetPort: 80 }]
---
apiVersion: v1
kind: Pod
metadata:
  name: client
  namespace: secure
  labels: { role: frontend }
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata:
  name: stranger
  namespace: secure
  labels: { role: guest }
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: default-deny
  namespace: secure
spec:
  podSelector: {}
  policyTypes: [Ingress, Egress]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: allow-dns
  namespace: secure
spec:
  podSelector: {}
  policyTypes: [Egress]
  egress:
    - to:
        - namespaceSelector:
            matchLabels: { kubernetes.io/metadata.name: kube-system }
          podSelector:
            matchLabels: { k8s-app: kube-dns }
      ports:
        - { protocol: UDP, port: 53 }
        - { protocol: TCP, port: 53 }
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: frontend-egress
  namespace: secure
spec:
  podSelector:
    matchLabels: { role: frontend }
  policyTypes: [Egress]
  egress:
    - to:
        - podSelector:
            matchLabels: { app: api }
      ports:
        - { protocol: TCP, port: 80 }
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: api-ingress
  namespace: secure
spec:
  podSelector:
    matchLabels: { app: api }
  policyTypes: [Ingress]
  ingress:
    - from:
        - podSelector:
            matchLabels: { role: frontend }
      ports:
        - { protocol: TCP, port: 80 }
EOF
kubectl -n "secure" rollout status "deployment/api" --timeout=240s
if ! kubectl -n "secure" wait --for=condition=Ready pod/client pod/stranger --timeout=180s; then
  kubectl -n "secure" describe pod client stranger >&2 || true
  exit 1
fi

(
case "${Q1_FAULT}" in
  dns-egress-port)
    kubectl -n "secure" patch networkpolicy "allow-dns" --type=json -p '[{"op":"replace","path":"/spec/egress/0/ports","value":[{"protocol":"UDP","port":5353},{"protocol":"TCP","port":5353}]}]'
    ;;
  dns-namespace-selector)
    kubectl -n "secure" patch networkpolicy "allow-dns" --type=json -p '[{"op":"replace","path":"/spec/egress/0/to/0/namespaceSelector/matchLabels","value":{"name":"kube-system"}}]'
    ;;
  dns-policy-deleted)
    kubectl -n "secure" delete networkpolicy allow-dns
    ;;
  dns-udp-only)
    kubectl -n "secure" patch networkpolicy "allow-dns" --type=json -p '[{"op":"replace","path":"/spec/egress/0/ports","value":[{"protocol":"TCP","port":53}]}]'
    ;;
  dns-pod-selector)
    kubectl -n "secure" patch networkpolicy "allow-dns" --type=json -p '[{"op":"replace","path":"/spec/egress/0/to/0/podSelector/matchLabels","value":{"k8s-app":"coredns"}}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
  egress-to-label)
    kubectl -n "secure" patch networkpolicy "frontend-egress" --type=json -p '[{"op":"replace","path":"/spec/egress/0/to/0/podSelector/matchLabels","value":{"app":"api-v2"}}]'
    ;;
  egress-port)
    kubectl -n "secure" patch networkpolicy "frontend-egress" --type=json -p '[{"op":"replace","path":"/spec/egress/0/ports/0/port","value":8080}]'
    ;;
  frontend-egress-deleted)
    kubectl -n "secure" delete networkpolicy frontend-egress
    ;;
  frontend-egress-selector)
    kubectl -n "secure" patch networkpolicy "frontend-egress" --type=json -p '[{"op":"replace","path":"/spec/podSelector/matchLabels","value":{"role":"front-end"}}]'
    ;;
  netpol-egress-ipblock-except)
    kubectl -n "secure" apply -f - <<< '{"apiVersion":"networking.k8s.io/v1","kind":"NetworkPolicy","metadata":{"name":"frontend-egress-ipblock"},"spec":{"podSelector":{"matchLabels":{"role":"frontend"}},"policyTypes":["Egress"],"egress":[{"to":[{"ipBlock":{"cidr":"0.0.0.0/0","except":["10.0.0.0/8","192.168.0.0/16"]}}],"ports":[{"protocol":"TCP","port":80}]},{"to":[{"namespaceSelector":{"matchLabels":{"kubernetes.io/metadata.name":"kube-system"}},"podSelector":{"matchLabels":{"k8s-app":"kube-dns"}}}],"ports":[{"protocol":"UDP","port":53},{"protocol":"TCP","port":53}]}]}}'
    kubectl -n "secure" delete networkpolicy frontend-egress --ignore-not-found >/dev/null
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_3}" in
  ingress-port)
    kubectl -n "secure" patch networkpolicy "api-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/ports/0/port","value":8080}]'
    ;;
  ingress-from-label)
    kubectl -n "secure" patch networkpolicy "api-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/from/0/podSelector/matchLabels","value":{"role":"front-end"}}]'
    ;;
  ingress-namespace-and)
    kubectl -n "secure" patch networkpolicy "api-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/from/0","value":{"namespaceSelector":{"matchLabels":{"team":"frontend"}},"podSelector":{"matchLabels":{"role":"frontend"}}}}]'
    ;;
  ingress-pod-selector)
    kubectl -n "secure" patch networkpolicy "api-ingress" --type=json -p '[{"op":"replace","path":"/spec/podSelector/matchLabels","value":{"app":"api-v2"}}]'
    ;;
  ingress-ports-cleared)
    kubectl -n "secure" patch networkpolicy "api-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/ports","value":[{"protocol":"TCP","port":443}]}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
# The question only makes sense if the client really is cut off.
for _ in $(seq 1 30); do
  kubectl -n "secure" exec client -- wget -qO- -T 3 "http://api" 2>/dev/null | grep -q nginx || exit 0
  sleep 2
done
echo "the client can still reach api" >&2
exit 1
)
